CREATE OR REPLACE FUNCTION public.gridex_assert_company_operational_for_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_company_status text;
begin
  if new.company_id is null then
    return new;
  end if;

  select status into v_company_status
  from public.companies
  where id = new.company_id;

  if coalesce(v_company_status, 'active') not in ('active', 'onboarding') then
    raise exception 'Tenant % is %, write is blocked for operational data', new.company_id, v_company_status
      using errcode = 'P0001';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_audit_critical_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
      declare
        v_old jsonb := case when TG_OP in ('UPDATE','DELETE') then to_jsonb(OLD) else null end;
        v_new jsonb := case when TG_OP in ('INSERT','UPDATE') then to_jsonb(NEW) else null end;
        v_company_id uuid := null;
        v_actor uuid := null;
        v_entity_id text := null;
      begin
        if TG_TABLE_NAME = 'audit_logs' then
          return coalesce(NEW, OLD);
        end if;

        v_company_id := nullif(coalesce(v_new ->> 'company_id', v_old ->> 'company_id'), '')::uuid;
        if v_company_id is null and TG_TABLE_NAME = 'companies' then
          v_company_id := nullif(coalesce(v_new ->> 'id', v_old ->> 'id'), '')::uuid;
        end if;

        v_actor := nullif(coalesce(
          v_new ->> 'updated_by',
          v_new ->> 'created_by',
          v_new ->> 'actor_user_id',
          v_new ->> 'invited_by',
          v_new ->> 'paused_by',
          v_old ->> 'updated_by',
          v_old ->> 'created_by',
          v_old ->> 'actor_user_id',
          v_old ->> 'invited_by',
          v_old ->> 'paused_by'
        ), '')::uuid;

        v_entity_id := coalesce(v_new ->> 'id', v_old ->> 'id');

        insert into public.audit_logs (
          company_id,
          actor_user_id,
          entity_type,
          entity_id,
          action,
          old_values,
          new_values,
          metadata
        ) values (
          v_company_id,
          v_actor,
          TG_TABLE_NAME,
          v_entity_id,
          lower(TG_TABLE_NAME || '_' || TG_OP),
          v_old,
          v_new,
          jsonb_build_object(
            'source', 'gridex_audit_critical_row_change',
            'operation', TG_OP,
            'table', TG_TABLE_NAME
          )
        );

        return coalesce(NEW, OLD);
      end;
      $function$

CREATE OR REPLACE FUNCTION public.gridex_contract_energy_direction_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_expected text;
begin
  if tg_table_name='contract_product_versions' then
    select energy_direction into v_expected
    from public.contract_products
    where id=new.contract_product_id;
  elsif tg_table_name='contract_publication_versions' then
    select energy_direction into v_expected
    from public.contract_product_versions
    where id=new.contract_product_version_id;
  elsif tg_table_name='public_contract_offers' then
    if new.contract_publication_version_id is not null then
      select energy_direction into v_expected
      from public.contract_publication_versions
      where id=new.contract_publication_version_id;
    elsif new.contract_product_version_id is not null then
      select energy_direction into v_expected
      from public.contract_product_versions
      where id=new.contract_product_version_id;
    elsif new.source_contract_offer_id is not null then
      select energy_direction into v_expected
      from public.contract_offers
      where id=new.source_contract_offer_id
        and company_id=new.company_id;
    elsif new.contract_product_id is not null then
      select energy_direction into v_expected
      from public.contract_products
      where id=new.contract_product_id;
    else
      v_expected:=coalesce(
        nullif(new.energy_direction,''),
        nullif(new.metadata->>'energy_direction',''),
        'consumption'
      );
    end if;
  else
    raise exception using errcode='42809',message='energy_direction_guard_wrong_table';
  end if;

  if v_expected is null or v_expected not in ('consumption','production') then
    raise exception using errcode='23514',message='canonical_energy_direction_missing';
  end if;
  if new.energy_direction is not null and new.energy_direction<>v_expected then
    raise exception using errcode='23514',message='canonical_energy_direction_mismatch';
  end if;
  new.energy_direction:=v_expected;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_contract_offer_slug_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_supplied text:=nullif(btrim(new.slug),'');
  v_legacy_generated text:=nullif(
    lower(trim(both '-' from regexp_replace(coalesce(new.name,''),'[^a-zA-Z0-9]+','-','g'))),
    ''
  );
begin
  -- Detect the legacy ASCII-only generated value and regenerate from name
  -- before Swedish characters have been lost.
  if v_supplied is null or v_supplied=v_legacy_generated then
    new.slug:=public.gridex_contract_slugify(new.name);
  else
    new.slug:=public.gridex_contract_slugify(v_supplied);
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_contract_product_version_integrity_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_expected_hash text;
begin
  if nullif(new.commercial_snapshot->>'contract_type', '')
       is distinct from new.contract_type then
    raise exception using
      errcode = '23514',
      message = 'contract_product_version_snapshot_contract_type_mismatch';
  end if;

  if nullif(new.commercial_snapshot->>'energy_direction', '')
       is distinct from new.energy_direction then
    raise exception using
      errcode = '23514',
      message = 'contract_product_version_snapshot_energy_direction_mismatch';
  end if;

  v_expected_hash :=
    encode(digest(new.commercial_snapshot::text, 'sha256'), 'hex');
  if new.content_sha256 is distinct from v_expected_hash then
    raise exception using
      errcode = '23514',
      message = 'contract_product_version_content_hash_mismatch',
      detail = jsonb_build_object(
        'expected', v_expected_hash,
        'received', new.content_sha256
      )::text;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_contract_publication_revision_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_company_id uuid;
  v_channel text;
  v_entity_id text;
  v_assignment_id uuid;
  v_publication_id uuid;
  v_publication_version_id uuid;
  v_option_id uuid;
  v_row jsonb;
begin
  v_row:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_entity_id:=v_row->>'id';
  if tg_table_name='public_contract_offers' then
    v_company_id:=(v_row->>'company_id')::uuid;
    v_channel:='website';
  elsif tg_table_name='tenant_contract_channels' then
    v_assignment_id:=(v_row->>'assignment_id')::uuid;
    v_channel:=v_row->>'channel';
    select company_id into v_company_id
    from public.tenant_contract_assignments where id=v_assignment_id;
  elsif tg_table_name='contract_publications' then
    v_assignment_id:=(v_row->>'assignment_id')::uuid;
    v_channel:=v_row->>'channel';
    select company_id into v_company_id
    from public.tenant_contract_assignments where id=v_assignment_id;
  elsif tg_table_name='contract_publication_versions' then
    v_publication_id:=(v_row->>'contract_publication_id')::uuid;
    select a.company_id,p.channel into v_company_id,v_channel
    from public.contract_publications p
    join public.tenant_contract_assignments a on a.id=p.assignment_id
    where p.id=v_publication_id;
  elsif tg_table_name='contract_price_options' then
    v_company_id:=(v_row->>'company_id')::uuid;
    v_publication_version_id:=nullif(
      v_row->>'contract_publication_version_id',''
    )::uuid;
    if v_publication_version_id is not null then
      select p.channel into v_channel
      from public.contract_publication_versions pv
      join public.contract_publications p on p.id=pv.contract_publication_id
      where pv.id=v_publication_version_id;
    end if;
  elsif tg_table_name='contract_price_option_area_prices' then
    v_option_id:=(v_row->>'contract_price_option_id')::uuid;
    select o.company_id,o.contract_publication_version_id
      into v_company_id,v_publication_version_id
    from public.contract_price_options o where o.id=v_option_id;
    if v_publication_version_id is not null then
      select p.channel into v_channel
      from public.contract_publication_versions pv
      join public.contract_publications p on p.id=pv.contract_publication_id
      where pv.id=v_publication_version_id;
    end if;
  end if;
  if v_company_id is not null and v_channel in ('website','api') then
    perform public.gridex_bump_contract_publication_revision(
      v_company_id,v_channel,tg_table_name||'.'||lower(tg_op),v_entity_id
    );
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_commercial_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_readiness jsonb;
begin
  if new.lifecycle_status in ('published','paused')
    and (
      tg_op='INSERT'
      or old.lifecycle_status is distinct from new.lifecycle_status
    ) then
    v_readiness:=public.gridex_validate_commercial_model_v1(
      new.company_id,new.contract_product_version_id
    );
    if not coalesce((v_readiness->>'ready')::boolean,false) then
      raise exception using
        errcode='23514',
        message='commercial_model_not_ready',
        detail=v_readiness::text;
    end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_quote_canonical_identity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_publication public.contract_publication_versions%rowtype;
  v_product_version public.contract_product_versions%rowtype;
  v_product_company_id uuid;
  v_publication_company_id uuid;
  v_price_plan_company_id uuid;
  v_price_book_company_id uuid;
  v_legal_company_id uuid;
begin
  if new.contract_product_id is null
     or new.contract_product_version_id is null
     or new.contract_publication_version_id is null
     or new.price_plan_id is null
     or new.price_plan_version_id is null
     or new.price_book_id is null
     or new.legal_bundle_version_id is null
     or new.energy_direction is null then
    raise exception using errcode='23502',message='quote_canonical_identity_incomplete';
  end if;

  select * into v_publication
  from public.contract_publication_versions
  where id=new.contract_publication_version_id;
  if not found then
    raise exception using errcode='23503',message='quote_publication_version_not_found';
  end if;

  select * into v_product_version
  from public.contract_product_versions
  where id=new.contract_product_version_id;
  if not found then
    raise exception using errcode='23503',message='quote_product_version_not_found';
  end if;

  select company_id into v_product_company_id
  from public.contract_products
  where id=new.contract_product_id;
  if v_product_company_id is not null and v_product_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_contract_product_tenant_mismatch';
  end if;

  select assignment.company_id into v_publication_company_id
  from public.contract_publications publication
  join public.tenant_contract_assignments assignment
    on assignment.id=publication.assignment_id
  where publication.id=v_publication.contract_publication_id;
  if v_publication_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_publication_tenant_mismatch';
  end if;

  select company_id into v_price_plan_company_id
  from public.price_plans
  where id=new.price_plan_id;
  if v_price_plan_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_price_plan_tenant_mismatch';
  end if;

  select company_id into v_price_book_company_id
  from public.price_books
  where id=new.price_book_id;
  if v_price_book_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_price_book_tenant_mismatch';
  end if;

  select company_id into v_legal_company_id
  from public.legal_bundle_versions
  where id=new.legal_bundle_version_id;
  if v_legal_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_legal_bundle_tenant_mismatch';
  end if;

  if v_product_version.contract_product_id is distinct from new.contract_product_id
     or v_publication.contract_product_version_id is distinct from new.contract_product_version_id
     or v_publication.price_plan_id is distinct from new.price_plan_id
     or v_publication.price_plan_version_id is distinct from new.price_plan_version_id
     or v_publication.price_book_id is distinct from new.price_book_id
     or v_publication.legal_bundle_version_id is distinct from new.legal_bundle_version_id
     or v_publication.offer_reference is distinct from new.offer_reference
     or v_publication.customer_type not in (new.customer_type,'both')
     or v_product_version.energy_direction is distinct from new.energy_direction
     or v_publication.energy_direction is distinct from new.energy_direction then
    raise exception using errcode='23514',message='quote_canonical_identity_mismatch';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_is_current_session_allowed()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_status text;
  v_disabled_at timestamptz;
begin
  if v_user_id is null then
    return false;
  end if;
  if to_regclass('public.user_profiles') is null then
    return true;
  end if;
  if exists(
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'user_profiles'
      and column_name = 'disabled_at'
  ) then
    execute
      'select profile.user_status,profile.disabled_at
       from public.user_profiles profile where profile.id=$1'
    into v_status, v_disabled_at
    using v_user_id;
  else
    select profile.user_status
    into v_status
    from public.user_profiles profile
    where profile.id = v_user_id;
  end if;
  if coalesce(v_status, 'active') in (
    'disabled',
    'locked_security',
    'removed_from_company',
    'invitation_revoked'
  ) then
    return false;
  end if;
  return v_disabled_at is null;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_next_customer_number(p_company_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prefix text;
  v_existing_next bigint;
  v_number bigint;
begin
  if p_company_id is null then
    raise exception 'company_id is required';
  end if;

  v_prefix := public.gridex_default_customer_number_prefix(p_company_id);

  if v_prefix !~ '^[A-Z0-9]{2,12}$' then
    raise exception 'invalid customer number prefix: %', v_prefix;
  end if;

  select coalesce(max(nullif(substring(customer_number from '([0-9]+)$'), '')::bigint) + 1, 100001)
    into v_existing_next
  from public.customers
  where company_id = p_company_id
    and customer_number is not null;

  insert into public.company_customer_number_sequences(company_id, prefix, next_number)
  values (p_company_id, v_prefix, v_existing_next)
  on conflict (company_id) do nothing;

  update public.company_customer_number_sequences
     set next_number = greatest(next_number, v_existing_next) + 1,
         prefix = v_prefix,
         updated_at = now()
   where company_id = p_company_id
   returning prefix, next_number - 1 into v_prefix, v_number;

  if v_number is null then
    raise exception 'customer number sequence could not be reserved';
  end if;

  return v_prefix || '-' || v_number::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_public_catalog_dependency_revision_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_row jsonb := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_company_id uuid;
  v_entity_id text := v_row->>'id';
begin
  case tg_table_name
    when 'companies' then v_company_id := (v_row->>'id')::uuid;
    when 'tenant_contract_assignments' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_offers' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_products' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_product_versions' then
      select cp.company_id into v_company_id from public.contract_products cp where cp.id = nullif(v_row->>'contract_product_id','')::uuid;
    when 'legal_bundle_versions' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'legal_bundle_version_documents' then
      select lb.company_id into v_company_id from public.legal_bundle_versions lb where lb.id = nullif(v_row->>'legal_bundle_version_id','')::uuid;
    when 'tenant_legal_profiles' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plans' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plan_versions' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_books' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'integration_api_clients' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolios' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolio_monthly_settlements' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    else v_company_id := null;
  end case;
  if v_company_id is not null then
    perform public.gridex_bump_contract_publication_revision(v_company_id,'website',tg_table_name || '.' || lower(tg_op),v_entity_id);
    perform public.gridex_bump_contract_publication_revision(v_company_id,'api',tg_table_name || '.' || lower(tg_op),v_entity_id);
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_publication_compatibility_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_company_id uuid;
  v_forward_id uuid;
begin
  if new.legacy_public_contract_offer_id is null then return new; end if;
  if current_setting('gridex.publication_link_repair',true)='on' then return new; end if;
  select po.company_id,po.contract_publication_version_id
    into v_company_id,v_forward_id
  from public.public_contract_offers po
  where po.id=new.legacy_public_contract_offer_id;
  if not found then
    raise exception using errcode='23503',message='legacy_public_contract_offer_not_found';
  end if;
  if v_forward_id is distinct from new.id then
    raise exception using errcode='23514',message='publication_version_link_mismatch';
  end if;
  if not exists(
    select 1
    from public.contract_publications cp
    join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
    where cp.id=new.contract_publication_id and ta.company_id=v_company_id
  ) then
    raise exception using errcode='23514',message='publication_company_mismatch';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_reject_locked_row_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_transition boolean:=coalesce(
    current_setting('gridex.version_transition',true),'')='on';
  v_publication_repair boolean:=coalesce(
    current_setting('gridex.publication_graph_repair',true),'')='on';
  v_old jsonb;
  v_new jsonb;
  v_allowed text[];
  v_expected_price_options jsonb;
begin
  if nullif(to_jsonb(old)->>'locked_at','') is null
     and nullif(to_jsonb(old)->>'published_at','') is null then
    return case when tg_op='DELETE' then old else new end;
  end if;
  if not v_transition then
    raise exception using errcode='55000',message='immutable_version_locked';
  end if;
  if tg_op='DELETE' then return old; end if;

  v_allowed:=case tg_table_name
    when 'contract_product_versions'
      then array['status','approved_at','approved_by','locked_at']
    when 'legal_template_versions'
      then array['status','reviewed_by','reviewed_at','published_at','locked_at']
    when 'legal_bundle_versions'
      then array['status','published_at','locked_at']
    when 'contract_publication_versions'
      then array['status','valid_from','valid_to','published_at','locked_at',
        'legacy_public_contract_offer_id']
    when 'tenant_legal_overrides'
      then array['status','submitted_at','reviewed_at','reviewed_by',
        'review_notes','locked_at']
    else array[]::text[]
  end;

  if tg_table_name='contract_publication_versions'
     and v_publication_repair then
    if current_user not in ('postgres','supabase_admin','service_role')
       and not pg_has_role(current_user,'service_role','member') then
      raise exception using errcode='42501',
        message='PUBLICATION_REPAIR_ROLE_REQUIRED';
    end if;
    if old.publication_snapshot->'commercial_snapshot'
       is distinct from new.publication_snapshot->'commercial_snapshot' then
      raise exception using errcode='55000',
        message='locked_publication_commercial_snapshot_is_immutable';
    end if;
    v_expected_price_options:=
      public.gridex_publication_price_options_json_v1(new.id);
    if coalesce(new.publication_snapshot->'price_options','[]'::jsonb)
       is distinct from v_expected_price_options then
      raise exception using errcode='23514',
        message='PUBLICATION_PRICE_OPTION_SNAPSHOT_MISMATCH';
    end if;
    if new.content_sha256 is distinct from encode(
      extensions.digest(new.publication_snapshot::text,'sha256'),'hex') then
      raise exception using errcode='23514',
        message='PUBLICATION_SNAPSHOT_INVALID';
    end if;
    v_allowed:=v_allowed||array['publication_snapshot','content_sha256'];
  end if;

  v_old:=to_jsonb(old)-v_allowed;
  v_new:=to_jsonb(new)-v_allowed;
  if v_old is distinct from v_new then
    raise exception using errcode='55000',
      message='immutable_version_content_changed';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_set_contract_version_legal_modules()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_required text[]; v_production boolean:=false;
begin
  v_production:=coalesce((new.commercial_snapshot#>>'{pricing_snapshot,production,enabled}')::boolean,false)
    or coalesce((new.commercial_snapshot#>>'{production,enabled}')::boolean,false)
    or coalesce((new.commercial_snapshot#>>'{pricing_snapshot,production_enabled}')::boolean,false)
    or coalesce((new.commercial_snapshot->>'production_enabled')::boolean,false);
  v_required:=public.gridex_required_legal_modules(new.customer_type,new.contract_type,'website',coalesce(new.automatic_renewal,false),coalesce(new.power_of_attorney_required,true),v_production);
  select coalesce(array_agg(distinct m order by m),'{}') into new.required_legal_modules
  from unnest(coalesce(new.required_legal_modules,'{}')||v_required) m;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_validate_contract_pricing_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.price_plan_id is not null and not exists(
    select 1 from public.price_plans p where p.id=new.price_plan_id and p.company_id=new.company_id
  ) then raise exception 'Prisplanen tillhör inte bolaget.' using errcode='23514'; end if;

  if new.price_plan_version_id is not null and not exists(
    select 1 from public.price_plan_versions v
    where v.id=new.price_plan_version_id and v.company_id=new.company_id and v.price_plan_id=new.price_plan_id
  ) then raise exception 'Prisversionen tillhör inte bolaget eller vald prisplan.' using errcode='23514'; end if;

  if new.price_book_id is not null and not exists(
    select 1 from public.price_books b
    where b.id=new.price_book_id and b.company_id=new.company_id
      and (new.price_plan_id is null or b.price_plan_id=new.price_plan_id)
      and (new.price_plan_version_id is null or b.price_plan_version_id=new.price_plan_version_id)
  ) then raise exception 'Prislistan tillhör inte bolaget eller vald prisversion.' using errcode='23514'; end if;
  return new;
end $function$

